"""Inspect the workspace: list files and inspect any SQLite databases found."""

import os
import sqlite3

root = os.getcwd()
print(f"Workspace: {root}")
print("\nFiles and directories:")
for entry in sorted(os.listdir(root)):
    full = os.path.join(root, entry)
    kind = "dir" if os.path.isdir(full) else "file"
    size = os.path.getsize(full) if os.path.isfile(full) else "-"
    print(f"  {kind:4s} {size:>10}  {entry}")

print("\nSQLite databases found:")
db_candidates = []
for entry in sorted(os.listdir(root)):
    full = os.path.join(root, entry)
    if os.path.isfile(full) and (
        entry.endswith((".db", ".sqlite", ".sqlite3"))
        or full.endswith(".sql3")
    ):
        db_candidates.append(full)

if not db_candidates:
    print("  (none)")
else:
    for db in db_candidates:
        print(f"\n  {db}:")
        try:
            with sqlite3.connect(db) as conn:
                conn.row_factory = sqlite3.Row
                tables = conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("    (no tables)")
                for row in tables:
                    name = row["name"]
                    cols = conn.execute(f'PRAGMA table_info("{name}")').fetchall()
                    col_desc = ", ".join(c["name"] for c in cols)
                    print(f"    table {name}: columns = {col_desc}")
        except sqlite3.Error as exc:
            print(f"    could not inspect: {exc}")

"""Tests for the login/registration module (uses a temporary database)."""

import os
import sqlite3
import tempfile
import unittest

import login


class LoginTestBase(unittest.TestCase):
    def setUp(self):
        fd, self.db_path = tempfile.mkstemp(suffix=".db")
        os.close(fd)
        self.conn = sqlite3.connect(self.db_path)
        self.conn.row_factory = sqlite3.Row
        login.ensure_schema(self.conn)
        self.conn.commit()

    def tearDown(self):
        self.conn.close()
        os.unlink(self.db_path)


class RegistrationTests(LoginTestBase):
    def test_register_and_login_success(self):
        user_id = login.register_user(
            self.conn, "alice.smith", "alice@example.com", "correct-horse"
        )
        self.assertIsInstance(user_id, int)
        row = login.verify_login(self.conn, "alice.smith", "correct-horse")
        self.assertIsNotNone(row)
        self.assertEqual(row["email"], "alice@example.com")
        self.assertEqual(row["access_rights"], "user")

    def test_login_wrong_password(self):
        login.register_user(
            self.conn, "alice.smith", "alice@example.com", "correct-horse"
        )
        self.assertIsNone(login.verify_login(self.conn, "alice.smith", "wrong-pass"))

    def test_login_unknown_user(self):
        self.assertIsNone(login.verify_login(self.conn, "nobody", "whatever123"))

    def test_duplicate_username_rejected(self):
        login.register_user(
            self.conn, "alice.smith", "alice@example.com", "correct-horse"
        )
        with self.assertRaises(ValueError):
            login.register_user(
                self.conn, "alice.smith", "other@example.com", "another-pass"
            )

    def test_duplicate_email_rejected(self):
        login.register_user(
            self.conn, "alice.smith", "alice@example.com", "correct-horse"
        )
        with self.assertRaises(ValueError):
            login.register_user(
                self.conn, "bob.jones", "alice@example.com", "another-pass"
            )

    def test_short_password_rejected(self):
        with self.assertRaises(ValueError):
            login.register_user(
                self.conn, "alice.smith", "alice@example.com", "short"
            )

    def test_password_hash_format_matches_existing_rows(self):
        user_id = login.register_user(
            self.conn, "alice.smith", "alice@example.com", "correct-horse"
        )
        row = self.conn.execute(
            "SELECT password_hash FROM users WHERE id = ?", (user_id,)
        ).fetchone()
        self.assertRegex(row["password_hash"], r"^[0-9a-f]{64}$")


if __name__ == "__main__":
    unittest.main()

